def moveZeroes(numbers: Array[Int]): Unit = {
  var writeIndex = 0

  for (readIndex <- numbers.indices) {
    val currentNumber = numbers(readIndex)

    if (currentNumber != 0) {
      numbers(writeIndex) = currentNumber
      writeIndex += 1
    }
  }

  while (writeIndex < numbers.length) {
    numbers(writeIndex) = 0
    writeIndex += 1
  }
}

